<?php
namespace App\Http\Controllers\Auth;
use App\Http\Controllers\Controller; use Illuminate\Http\Request; use Illuminate\Http\RedirectResponse; use Illuminate\Support\Facades\Auth; use Illuminate\Validation\ValidationException; use Inertia\Inertia; use Inertia\Response;
class AuthenticatedSessionController extends Controller { public function create():Response{return Inertia::render('Auth/Login');} public function store(Request $r):RedirectResponse{$credentials=$r->validate(['email'=>['required','email'],'password'=>['required','string']]);if(!Auth::attempt($credentials,$r->boolean('remember')))throw ValidationException::withMessages(['email'=>'The credentials do not match our records.']);$r->session()->regenerate();abort_unless($r->user()->is_admin,403);return redirect()->intended(route('admin.dashboard'));} public function destroy(Request $r):RedirectResponse{Auth::guard('web')->logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/');} }
